"dp.facesHead": "One number, three faces",
"dp.facesNote": "The sphere in the last scene is the brightness face, wrapped around a ball.",
"dp.badge": "⊥  a·b = 0",
"dp.step0": "Two arrows **a** and **b** start at the origin with an angle θ between them. The third side of the triangle is the arrow **a** − **b**, from the tip of **b** to the tip of **a** (lesson 1.1). Drag the tips: the triangle follows.",
"dp.step1": "Every side can already be measured: |**a**|² = Σaᵢ², |**b**|² = Σbᵢ² (lesson 1.3) and |**a** − **b**|² = Σ(aᵢ − bᵢ)² (lesson 0.3). Three squares, three sums; the table below adds them up.",
"dp.step2": "The law of cosines (lesson 0.5) ties the three sides to the corner: |**a** − **b**|² = |**a**|² + |**b**|² − 2|**a**||**b**| cos θ. In lesson 0.5 that last term was two strips, each of area |**a**|·|**b**| cos θ.",
"dp.step3": "Now write the same left side in components and expand each square the usual way: (aᵢ − bᵢ)² = aᵢ² − 2aᵢbᵢ + bᵢ². The new table column aᵢbᵢ holds the products.",
"dp.step4": "Regroup: the aᵢ² add up to |**a**|² and the bᵢ² to |**b**|², the squares you already have. The only new thing is the cross term −2Σaᵢbᵢ: minus twice the sum of products of matching components.",
"dp.step5": "Put the two descriptions of |**a** − **b**|² face to face: one from the law of cosines, one from the components.",
"dp.step6": "|**a**|² appears on both sides: cancel it. |**b**|² too. Only the two cross terms survive.",
"dp.step7": "Divide by −2. Left: the sum of products of matching components. Right: the lengths times the cosine of the angle. Two computations, one number: drag **a** or **b** and watch both stay equal.",
"dp.step8": "Name it: **a**·**b**, the dot product. The components give it without measuring any angle; the geometry says what it means: |**a**||**b**| cos θ. And lesson 0.5 already drew it: |**a**| times the shadow of **b** on **a** is a rectangle whose area is **a**·**b**. One number, three faces; the third face lights a sphere in the last scene.",
"dp.ch1": "Find **a** and **b** with Σaᵢbᵢ = 0 while neither arrow is zero.",
"dp.ch1Hint": "Swap the components of **a** and flip one sign: **b** = (−a₂, a₁).",
"dp.ch2": "Make the two routes give a negative number.",
"dp.ch2Success": "Past 90° the shadow points backwards: the rectangle turns hatched and its area counts as negative.",
"dp.ch3": "Make **a**·**b** = |**a**|².",
"dp.ch3Success": "**b** = **a** does it, and so does any **b** whose shadow on **a** is exactly |**a**| long; lesson 1.5 shows why.",
"dp.ch4": "Make **a**·**b** = 0 without making either arrow zero.",
"dp.ch4Hint": "Drag **b** toward the dashed line.",
"dp.ch4Hint2": "A whole-number answer: **a** = (2, 1), **b** = (−1, 2).",
"dp.ch5": "Keep **a** fixed and make **a**·**b** as large as you can with |**b**| = 2.",
"dp.ch6": "Find **b** with |**b**| = 2 and **a**·**b** = −2|**a**|, the most negative it can be.",
"dp.ch7": "Make the brightness face read 0.500: a lamp at 60°.",
"dp.ch8": "Make **a**·**b** = 0 in 3D without making either arrow zero.",
"dp.ch9": "Put **b** on the far side of the disc (**a**·**b** < 0) while keeping b₃ > 0.",
"dp.ch10": "Put P on the terminator.",
"dp.ch10Hint": "The dashed circle is every point with N·L = 0: the perpendicular line of DP-2, bent around the sphere by a nearby lamp.",
"dp.ch11": "Make P as bright as possible without moving the light.",
"dp.ch12": "Switch on raw N·L and find the darkest point.",
