"lc.cut0": "Three squares, one on each side. Pythagoras promises a² + b² = c², but only for a square corner. Here a² + b² = {a2} + {b2} = {pyth}, and c² = {c2}. ",
"lc.cutZero": "The corner is square and the two numbers agree: this is Pythagoras, nothing is missing.",
"lc.cutMissing": "{missing} units of area are missing. Where did they go?",
"lc.cutExtra": "c² is bigger than a² + b² by {extra}. Where did the extra area come from? (A wide corner: the strips below will count as negative.)",
"lc.cut1": "Shine a light straight down onto side a. Side b casts a shadow of length b cos θ (lesson 0.4: cos is the shadow of a length-1 stick).",
"lc.cut2": "Cut a strip of that width off the square on a. Its area is a × (b cos θ).",
"lc.cut3": "Now light side b instead: a casts a shadow a cos θ on it. Cut that strip off the square on b. Its area is b × (a cos θ), the same number. Two different rectangles, one area: a·b·cos θ.",
"lc.cut4": "What is left of the two squares: a rectangle a × DB and a rectangle b × EA.",
"lc.cut5": "The square on c can be split too: drop the height from C onto c and extend it. Two rectangles, c × FB and c × AF.",
"lc.cut6": "Watch the leftover of a move. First it leans: sliding the top edge sideways keeps the base and the height, so the area does not change.",
"lc.cut7": "Then it turns a quarter turn around B. Turning changes nothing about area.",
"lc.cut8": "Lean it back upright: it is exactly the rectangle c × FB. The leftover of a has become the first part of c².",
"lc.cut9": "The leftover of b does the same dance around A (lean, quarter turn counter-clockwise, lean) and lands as c × AF. Together they fill the square on c: c² = a·DB + b·EA.",
"lc.cut10": "Now count the area. The leftovers were the squares minus the strips. So c² = a² + b² − (strip) − (strip) = a² + b² − 2·a·b cos θ. Drag θ to 90°: the shadows shrink to a point, the strips vanish, and this is Pythagoras; in fact, the dance you just watched is Euclid's own proof of it. Drag past 90°: the shadows point backwards, the strips flip to hatched (negative area) and get *added*.",
"lc.cut11": "One more look at the strip: its area is the length of side a times the shadow of side b on it. In the next lessons the sides become arrows, written in bold **a**, **b**, with lengths |**a**|, |**b**|; the strip is |**a**| (|**b**| cos θ). Lesson 1.4 gives that product a name, the dot product **a**·**b**, a new meaning of the dot (not plain multiplication), and shows it needs no angle at all. So the law of cosines reads |**a** − **b**|² = |**a**|² + |**b**|² − 2 **a**·**b**: a Pythagoras with two rectangles cut out.",
"lc.cut4Debt": " Here a strip is wider than its square: the hatched leftover is a debt, an area with a minus sign.",
"lc.cutNoSquare": " c = 0: there is no square on c; move A to continue.",
"lc.proof0": "Your triangle again: sides a and b meet at C with angle θ = {th}°; c is the gap. ",
"lc.proofRight": "The corner is square, so Pythagoras already applies; the steps below show why the general formula agrees with it.",
"lc.proofNotRight": "No square corner, so Pythagoras does not apply, yet.",
"lc.proof1": "Drop a perpendicular from A onto the line of a. Call the foot D. Now there ARE right angles.",
"lc.proof2": "CD is the shadow of b on a: CD = b cos θ. The height AD = b sin θ.",
"lc.proof3": "The rest of side a is DB = a − b cos θ. (If θ > 90°, b cos θ is negative and D is behind C: DB is longer than a. The formula does not care.)",
"lc.proof4": "Triangle ADB is right-angled at D. Pythagoras: c² = DB² + AD².",
"lc.proof5": "Substitute the two legs we named.",
"lc.proof6": "Expand the square: (a − b cos θ)² = a² − 2ab cos θ + b² cos² θ. The middle term is the correction: it is the two strips of the first scene, written as algebra.",
"lc.proof7": "b² cos² θ + b² sin² θ: two pieces of the same square.",
"lc.proof8": "cos² θ + sin² θ = 1 (the unit-circle point is at distance 1). The two pieces merge into b².",
"lc.proof9": "Done: c² = a² + b² − 2ab cos θ. Drag θ to 90°: cos θ = 0 and this is Pythagoras.",
"lc.proof2Zero": " Right now θ = 90°, so the shadow is zero and D sits on C.",
"lc.proof4Flat": " θ = 0° or 180° is the flattened case: AD = 0 and the proof still holds.",
"lc.cutTransport": "Movement within the selected step. Pause or scrub to inspect the lean and the turn; this does not advance the explanation.",
"lc.fadeTransport": "Inspect the two tiles fading into the square on b. This controls opacity, not area or the explanation step.",
