"lc.ch1": "Make both strips disappear.",
"lc.ch1Hint": "Set θ to 90°.",
"lc.ch2": "Make the strips negative (hatched) and watch c grow past √(a² + b²).",
"lc.ch3": "Find a triangle where a strip is wider than its square.",
"lc.ch3Hint": "A short a, a long b and a small θ: try a = 1, b = 4, θ = 30°.",
"lc.ch4": "Make the two strips *look* the same, not just measure the same.",
"lc.ch4Success": "a = b: the strips are congruent. For a ≠ b they only share the area (at 0° or 180° the two rectangles are the same shape turned on its side).",
"lc.ch5": "Make the correction disappear without touching a or b.",
"lc.ch6": "Make c longer than a + b.",
"lc.ch6Success": "c ≤ a + b always: at 180° you reach equality (the triangle inequality).",
"lc.ch7": "Make c = 5 with a = 3, b = 4.",
"lc.ch8": "Find the step where the correction term is born.",
"lc.ch8Hint": "Select the expansion step (7 / 10), even after jumping to the end.",
"lc.ch9": "Put the hand exactly where the elbow is straight (φ = 180°) and still reachable.",
"lc.ch10": "Make the solver clamp.",
"lc.ch10Success": "Your rig does this silently: without the clamp, acos returns NaN and the bone disappears.",
"lc.ch11": "Find a target with φ = 90°.",
"lc.ch11Hint": "Pythagoras: which d makes the strips of the first scene vanish?",
"lc.ch11Hint2": "With L₁ = 2 and L₂ = 1.5 that is d = 2.5, for example the target (2.5, 0).",
