"ve.ch4": "Turn on **Position**, then move the tip to the point **(5, 5)**.",
"ve.ch4Success": "As a position, the numbers are the address: every move changed them.",
"ve.ch5": "Translate the floor by **T = (3, 3)** and read the normal.",
"ve.ch5Success": "Every vertex moved by T; the normal is the same as before.",
"ve.ch6": "Turn on **N like a point** to see what goes wrong when a normal gets the translation.",
"ve.ch6Success": "N + T tilts and stretches the normal. That is why directions carry w = 0.",
"ve.ch7": "Make **v** point straight up, with length 2.",
