"ve.ch8": "Make **v** lie flat on the floor, without making it zero.",
"ve.ch9": "Move A and B so that **B − A = (−3, −4)**.",
"ve.ch9Hint": "Swap them: put A where B is and B where A is.",
"ve.ch10": "Slide the whole arrow until **A = (0, 0)**, keeping B − A = (3, 4).",
"ve.ch10Hint": "Drag the middle of the arrow: both points move together.",
"ve.ch10Success": "Now B = (3, 4) = B − A: measured from the origin, a point's position is a vector.",
"ve.ch11": "Make **B − A = (3, 4, 0)**, the trip of exercise 2: no change along z.",
"ve.ch11Hint": "Give A and B the same z; then put B 3 further along x and 4 higher along y.",
