"va.table": "Components, one row per axis",
"va.read1": "a + b = {ab}: walk a = {a}, then b = {b}; both orders end at the same corner. Its length is {nab}, while |a| + |b| = {sum}.",
"va.read1Zero": "a + b = (0.0, 0.0): b = {b} undoes a = {a}, and the walk ends where it started.",
"va.read2": "s·a = {sc} with s = {s}: the arrow is {f} times as long, same direction.",
"va.read2Neg": "s·a = {sc} with s = {s}: {f} times as long and turned around, because s is negative.",
"va.read2Zero": "s = 0: s·a is the zero vector, every component 0, no direction left.",
"va.read3": "r = s·a + t·b = {r} with s = {s}, t = {t}.",
"va.read3Line": " a and b lie on one line: every combination stays on that line.",
"va.read3Zero": " One of the arrows is zero: only the other one can be scaled.",
"va.read4": "r = s·a + t·b + u·c = {r}.",
"va.read4Plane": " With u = 0, r stays on the plane of a and b.",
"va.read5": "The corner P' = {p} with w₁ = {w1} and w₂ = {w2}; every other vertex moves by its own w₁Δ₁ + w₂Δ₂.",
"va.ch1": "Make **a + b = (0, 0)** without making **a** zero.",
"va.ch1Success": "b = −a: walking b undoes walking a.",
"va.ch2": "Make |**a** + **b**| equal |**a**| + |**b**|, with neither arrow zero.",
"va.ch2Hint": "Point a and b the same way, e.g. b = 2a.",
"va.ch2Success": "Lengths add only for arrows that point the same way; any angle between them makes the sum shorter.",
"va.ch3": "Turn **a** around without changing its length.",
"va.ch4": "Make **s·a** the zero vector.",
"va.ch4Success": "s = 0 gives (0, 0): the one vector with no direction.",
"va.ch5": "Reach **r = (5, 3)**.",
"va.ch5Hint": "With a = (1, 2) and b = (3, −1): the x components give s + 3t = 5, the y components 2s − t = 3.",
"va.ch6": "Switch on **Paint**, put **a** and **b** on one line and scrub s and t. What do the stamps fill?",
"va.ch6Hint": "Type b = 2a, or b = −a, in the panel.",
"va.ch6Success": "A line: two arrows on one line reach only that line, however you scrub.",
"va.ch7": "Lift **r** straight up to **(0, 3, 0)**.",
"va.ch7Hint": "Only c points up: switch off a and b with s = 0 and t = 0.",
"va.ch8": "Set **u = 0** and keep r away from the origin.",
"va.ch8Success": "r now lies on the plane of a and b: two arrows reach a plane, the third lifts you off it.",
"va.ch9": "Smile fully (**w₁ = 1**) and open the jaw until the corner is back at its base height.",
"va.ch9Hint": "The smile lifts the corner by 0.3, the jaw lowers it by 0.4·w₂.",
"va.ch10": "Make the face frown.",
"va.ch10Success": "A negative weight runs the delta backwards: weights can be any numbers.",
