  "cp.hintArea": "Parallelogram of a and b: area |a||b| sin θ = {area}",
  "cp.hintPerp": "The result is perpendicular to this input",
  "cp.idle1Mouse": "Drag the tips of a and b · orbit with LMB on empty space · tick order b × a in the [N] panel",
  "cp.idle1Touch": "Drag the tips of a and b · swipe sideways to orbit",
  "cp.hintSigned": "Signed area ax·by − ay·bx = {sa} · hatched when negative",
  "cp.hintTurn": "The shorter turn from a to b: its direction is the sign of the area",
  "cp.hintFace": "Face: N·L = {ndotl}, brightness max(0, N·L) = {bright}",
