  "cp.formula1": "Cross product and its length",
  "cp.formula2": "Signed area in 2D",
  "cp.formula3": "Triangle normal and lighting",
  "cp.tableCaption": "Each component is one product minus another",
  "cp.colPlus": "+ product",
  "cp.colMinus": "− product",
  "cp.colC": "= component",
  "cp.ch1": "Make the result point straight along +z: put a on the x axis and b on the y axis (both positive).",
  "cp.ch1Hint": "Type a = (1, 0, 0) and b = (0, 1, 0) in the N panel (on a phone: the chips under the scene).",
  "cp.ch1Success": "x × y = +z. That is the formula, in every coordinate system; the right-hand rule only describes how it looks in a right-handed one.",
  "cp.ch2": "Make a × b the zero vector without making a or b zero.",
  "cp.ch2Hint": "Point b along the same line as a, for example b = 2·a or b = −a.",
  "cp.ch3": "Make the parallelogram's area exactly 6.",
  "cp.ch3Hint": "Perpendicular arrows of lengths 2 and 3 do it, for example a = (2, 0, 0) and b = (0, 3, 0).",
  "cp.ch4": "Turn the result upside down without moving a or b.",
  "cp.ch5": "Make the signed area negative.",
  "cp.ch6": "With a = (2, 0), make the signed area exactly 6.",
  "cp.ch6Hint": "With a = (2, 0) the formula is 2·by − 0·bx: only the height of b counts.",
  "cp.ch7": "Make the area zero with two arrows that are not zero.",
  "cp.ch8": "Reverse the vertex order and turn culling off: the triangle is drawn, but black.",
  "cp.ch8Success": "The normal now points away from the light, so max(0, N·L) = 0. With culling on, the same triangle simply disappears.",
  "cp.ch9": "Keep the order A → B → C and move one vertex until the face turns black.",
  "cp.ch9Hint": "Pull C down through the line AB, for example C = (0, −2, 1): seen from the front, A → B → C now runs clockwise, and the normal swings to −z.",
  "cp.read1": "{name} = {c}. Its length {len} equals the area of the parallelogram, |a||b| sin θ = {area}. It is perpendicular to both inputs: ({name})·a = {ca}, ({name})·b = {cb}.",
  "cp.read1Swap": " The order is b × a: the same line and the same length as a × b, the opposite direction.",
  "cp.read1Par": "a and b lie on one line: the parallelogram is flat, its area is 0, and {name} = (0, 0, 0). The zero vector is a fine answer; only normalizing it fails.",
  "cp.read1Zero": "One arrow has zero length: there is no parallelogram, {name} = (0, 0, 0), and the angle θ is undefined.",
  "cp.read2Ccw": "ax·by − ay·bx = {p} − {q} = {sa}: positive, so the turn from a to b is counter-clockwise. The parallelogram's area is {abs}.",
  "cp.read2Cw": "ax·by − ay·bx = {p} − {q} = {sa}: negative, so the turn from a to b is clockwise and the parallelogram is hatched. Its area is still {abs}; the sign is only the orientation.",
  "cp.read2Line": "ax·by − ay·bx = {p} − {q} = {sa}: a and b lie on one line, the parallelogram is flat.",
  "cp.read3": "Order {order}: e₁ = {e1}, e₂ = {e2}, e₁ × e₂ = {n}, so N = {N}. N·L = {ndotl}, brightness max(0, N·L) = {bright}.",
  "cp.read3Lit": " The front of the face turns toward the light.",
  "cp.read3Dark": " The normal points away from the light: wherever the face is drawn, it is black.",
  "cp.read3Cull": " Back-face culling is on: the face is drawn only while its vertices run counter-clockwise on your screen, that is while N points toward the camera. Orbit behind it and it vanishes.",
  "cp.read3NoCull": " Culling is off: the face is drawn from both sides, always lit by this one normal.",
  "cp.read3Flat": "The three points lie on one line: e₁ × e₂ = (0, 0, 0), so there is no normal and no face to draw.",
