  "wd.read1": "Ruler {fn} with k = {k}: the products add up to x·r = {dot}. Its squared length is r·r = {rr}, so the signal holds {coef} copies of this ruler.",
  "wd.read1Perp": " The dot product is 0: the signal is perpendicular to this ruler, so none of this wave is in it.",
  "wd.read1Empty": "The sine ruler with k = {k} is all zeros (the sine is 0 at every sample), so it measures nothing. Switch sin off or choose another k.",
  "wd.readFast": " This signal was made by a k = 14 wave, yet its 16 numbers are exactly those of 1.5 × the k = 2 cosine ruler: sixteen samples cannot tell the two waves apart. That is aliasing.",
  "wd.readBetween": " This wave makes 2.5 turns in the window, between two rulers. No single ruler matches it, so a little of it shows up at every k. That is leakage.",
  "wd.read2": "Frequency {k}: {a} copies of the cosine ruler and {b} of the sine ruler, size {amp}. Σx² = {e1}, and the spectrum gives the same {e2}.",
  "wd.read3": "Rulers of frequencies 0 to {last} added back: the squared misses add up to {err}.",
  "wd.read3None": "K = 0: nothing added back yet, so the miss is the whole signal: {err}.",
  "wd.read3Exact": " Exact: every miss is 0.",
  "wd.read4": "{S} spinning sticks: the pen misses the drawing by {err} on average (squared distance), {rel}% of the miss with no stick at all.",
  "wd.ch1": "Find the ruler the current signal points along most strongly: the most copies, plus or minus.",
  "wd.ch1Hint": "Step k from 0 to 8 with sin off, then with sin on, and watch the copies row; the spectrum below shows all of them at once.",
