  "pt.formula3": "Distance in 3D, two steps",
  "pt.formula4": "Distance in n dimensions",
  "pt.formula5": "Squared distance against squared radius",
  "pt.dis0": "Four copies of the triangle sit in a square of side **a + b**, one right angle in each corner. Their long sides fence a tilted square of side c: the uncovered area is **c²**.",
  "pt.dis1": "Count the big square two ways. As one square: (a + b)² = {big}. As pieces: the four triangles take 4 · ½ab = {tris}, so the tilted square is c² = {c2}.",
  "pt.dis2": "Slide the top-right triangle down and to the left. It does not turn or change shape: it closes an a by b rectangle with the bottom-left copy.",
  "pt.dis3": "Slide the other two, one up and one to the right. They close a b by a rectangle in the opposite corner.",
  "pt.dis4": "Same big square, same four triangles, so the uncovered area is still {c2}. But now it is two squares: a² + b² = {a2} + {b2}. So **a² + b² = c²**.",
  "pt.room0": "Walk across the floor first: legs dx and dz with a right angle between them. Pythagoras on the floor: f² = dx² + dz² = {f2}.",
  "pt.room1": "Now go up by dy. The floor diagonal f and the vertical leg meet at a right angle: a new triangle, standing upright. Pythagoras again: d² = f² + dy² = {s2}.",
  "pt.room2": "Both steps together: d² = dx² + dy² + dz², d = {s}. Orbit the view: the right angles stay right angles from every side.",
  "pt.read1": "P = ({P}), Q = ({Q}): legs dx = {dx} and dy = {dy}; squares {dx2} + {dy2} = {d2}; straight line d = {d}, grid walk {walk}.",
  "pt.read1Line": " One leg is zero: the straight line runs along the grid, so it is exactly as long as the grid walk.",
  "pt.read1Negative": " A leg is negative because Q is left of or below P; its square is positive anyway, so the distance does not care.",
  "pt.read1Zero": "P and Q are the same point: both legs are 0 and the distance is 0.",
  "pt.read2": "a = {a}, b = {b}: big square (a + b)² = {big}; four triangles {tris}; uncovered c² = {c2}, c = {c}; and a² + b² = {a2} + {b2} = {c2}.",
  "pt.read3": "Floor: f² = dx² + dz² = {dx2} + {dz2} = {f2}. Up: d² = f² + dy² = {f2} + {dy2} = {s2}, so d = {s}.",
  "pt.read3Zero": "P and Q are the same point: every leg is 0 and the distance is 0.",
  "pt.read5": "X = ({x}, {y}): d² = {d2} and r² = {r2}. With roots: d = {d} and r = {r}.",
  "pt.read5In": " d² < r², so X is inside, and d < r says the same.",
  "pt.read5On": " d² = r², so X is exactly on the circle.",
  "pt.read5Out": " d² > r², so X is outside, and d > r says the same.",
  "pt.readN": "n = {n}: differences {legs}; squares {squares}; sum {d2}; distance d = {d}.",
