  "pt.ndCaption": "Differences and their squares, one row per dimension",
  "pt.ch1": "Make the distance exactly 5 with other points than (1, 2) and (4, 6).",
  "pt.ch1Hint": "Legs 3 and 4 work anywhere on the grid. So do legs 5 and 0.",
  "pt.ch2": "Make the straight line exactly as long as the grid walk.",
  "pt.ch2Hint": "When is a flight as long as the drive? When there is only one street to drive along.",
  "pt.ch2Success": "One leg is zero, so d = √(dx²) = |dx|: the triangle has collapsed into a line.",
  "pt.ch3": "Step the slide to the end and compare what is left uncovered.",
  "pt.ch4": "Find other sides a and b whose long side c is a whole number.",
  "pt.ch4Hint": "Scale the 3-4-5 triangle: multiply 3, 4 and 5 by the same number, for example 0.6.",
  "pt.ch5": "Put Q straight above P.",
  "pt.ch5Hint": "Give Q the same x and z as P; only the height y may differ.",
  "pt.ch5Success": "The floor diagonal is 0, so the distance is just the height |dy|.",
  "pt.ch6": "Find another box whose diagonal is exactly 3.",
  "pt.ch6Hint": "The legs 1, 2, 2 in another order, or 3, 0, 0.",
  "pt.ch7": "In 8 dimensions, make the distance exactly 5.",
  "pt.ch7Hint": "You need squares that add up to 25: 9 + 16, or 16 + 4 + 4 + 1, with every other difference 0.",
  "pt.ch8": "Put X exactly on the circle.",
  "pt.ch8Hint": "d² must equal r². With r = 2.5, the point (1.5, 2.0) works: 2.25 + 4 = 6.25.",
