  "pj.hintPerp": "perp = {perp}, at a right angle to b",
  "pj.hintTile": "{name} = {value}",
  "pj.hintU1": "Drag u₁ to turn both axes",
  "pj.hintU2": "Drag u₂ to change the angle between the axes",
  "pj.hintMiss": "The shadows rebuild a point {miss} away from a",
  "pj.hintN": "Drag n: it stays a unit vector, the plane turns with it",
  "pj.hintAn": "(a·n) n: the part along the normal, a·n = {an}",
  "pj.hintGround": "On the plane: {g}",
  "pj.hintPlane": "The plane through O perpendicular to n",
  "pj.stateNoAxis": "b = 0: there is no line to cast a shadow on",
  "pj.stateOblique": "The axes are not perpendicular: shadows are not coordinates here",
  "pj.readNoAxis": "b is the zero vector: it has no direction, so there is no line to project on. a·b = 0, but a·b̂ is undefined.",
  "pj.readPos": "a·b̂ = {s} at θ = {th}: the shadow points the way b points.",
  "pj.readNeg": "a·b̂ = {s} at θ = {th}: past 90° the shadow lies behind the start of b, so it is negative.",
  "pj.readZero": "a·b̂ = {s}: a is perpendicular to b (or zero), so it casts no shadow.",
  "pj.readSplit": "proj = {proj} (the same as (a·b)/(b·b) b = {alt}), perp = {perp}, perp·b = {dot}. Pythagoras: {na2} = {proj2} + {perp2}.",
  "pj.readOrtho": "Perpendicular unit axes: the shadows {sh1} and {sh2} are exactly the coordinates of a, and they rebuild a.",
  "pj.readOblique": "The shadows are {sh1} and {sh2}, but the coordinates are {co1} and {co2}: rebuilt from shadows, the arrow misses a by {miss}.",
  "pj.readPlane": "a·n = {an}; on the plane: {ground}; reflected: {refl}.",
  "pj.ch1": "Make the shadow negative.",
  "pj.ch1Success": "Past 90° the cosine is negative: the shadow lies behind the start of b.",
  "pj.ch2": "Make the shadow exactly 0 without making either arrow zero.",
  "pj.ch2Hint": "a must be perpendicular to b: with b = (3, 1), try a = (−1, 3).",
  "pj.ch3": "Make the shadow as long as **a** itself.",
  "pj.ch3Hint": "That happens only when a lies on the line of b, pointing the same way.",
  "pj.ch4": "Make the two small squares equal: |proj|² = |perp|².",
  "pj.ch4Hint": "That is a 45° angle between a and b.",
  "pj.ch5": "Turn the axes to φ = 45° and keep them perpendicular.",
  "pj.ch5Success": "New shadows, new numbers, and they still rebuild a: perpendicular unit axes always work.",
  "pj.ch6": "Tilt u₂ so the axes are no longer perpendicular.",
  "pj.ch6Success": "Now the shadows are not the coordinates, and adding them back misses a. The shortcut needs perpendicular unit axes.",
  "pj.ch7": "Put **a** in the plane: no part along the normal.",
  "pj.ch7Hint": "Make a·n = 0. With the floor normal (0, 1, 0), set the y component to 0.",
