  "du.unit0": "Two arrows, a and b.",
  "du.unit1": "Drop a perpendicular from the tip of b to the line of a: that is b's **shadow** on a.",
  "du.unit2": "Read the shadow on the line and multiply by |a|. That number is a·b.",
  "du.unit3": "Now forget the picture: write each arrow as its numbers, one coloured leg per component.",
  "du.unit4": "a's legs lie down in a row; b's legs stand up in a column.",
  "du.unit5": "The column passes the row. Where matching legs meet, they multiply: a **tile** whose area is aᵢbᵢ.",
  "du.unit6": "A negative times a positive is a negative tile: hatched, it will pull the stack down.",
  "du.unit7": "Add them up: the tiles drop into a **stack**.",
  "du.unit8": "The stack is exactly as tall as |a| × shadow. One computation, two faces.",
  "du.unit9": "Drag a or b, or change n. Everything is recomputed from the same numbers.",
