"dp.formula3": "Скалярное произведение в 3D",
"dp.lampFormula": "Яркость по Ламберту в точке P",
"dp.corrTip": "Поправка теоремы косинусов: две полосы площадью |a||b| cos θ каждая",
"dp.crossTip": "Перекрёстный член раскрытия: −2, умноженное на сумму произведений",
"dp.expandTip": "Каждый квадрат разности, раскрытый",
"dp.compCaption": "Компоненты a и b, шаг за шагом",
"dp.comp3Caption": "Компоненты и их произведения в 3D",
"dp.codeTabs": "Язык кода",
"dp.signLabel": "Знак a·b:",
"dp.sgnPos": "согласны (> 0)",
"dp.sgnPerp": "⊥ (= 0)",
"dp.sgnZero": "= 0, нет направления",
"dp.sgnNeg": "не согласны (< 0)",
"dp.facesHead": "Одно число, три лица",
"dp.facesNote": "Сфера в последней сцене — это лицо «яркость», натянутое на шар.",
"dp.badge": "⊥  a·b = 0",
"dp.step0": "Две стрелки **a** и **b** выходят из начала координат, между ними угол θ. Третья сторона треугольника — стрелка **a** − **b** от конца **b** к концу **a** (урок 1.1). Двигайте концы: треугольник следует за ними.",
"dp.step1": "Каждую сторону мы уже умеем измерить: |**a**|² = Σaᵢ², |**b**|² = Σbᵢ² (урок 1.3) и |**a** − **b**|² = Σ(aᵢ − bᵢ)² (урок 0.3). Три квадрата, три суммы; таблица ниже их складывает.",
"dp.step2": "Теорема косинусов (урок 0.5) связывает три стороны с углом: |**a** − **b**|² = |**a**|² + |**b**|² − 2|**a**||**b**| cos θ. В уроке 0.5 последний член был двумя полосами, каждая площадью |**a**|·|**b**| cos θ.",
"dp.step3": "Теперь запишем ту же левую часть через компоненты и раскроем каждый квадрат как обычно: (aᵢ − bᵢ)² = aᵢ² − 2aᵢbᵢ + bᵢ². В новом столбце таблицы aᵢbᵢ — сами произведения.",
"dp.step4": "Перегруппируем: aᵢ² складываются в |**a**|², bᵢ² — в |**b**|², эти квадраты у нас уже есть. Новое здесь только одно — перекрёстный член −2Σaᵢbᵢ: минус удвоенная сумма произведений соответствующих компонент.",
"dp.step5": "Поставим два описания |**a** − **b**|² лицом к лицу: одно из теоремы косинусов, другое из компонент.",
"dp.step6": "|**a**|² стоит в обеих частях — сокращаем. |**b**|² тоже. Остаются только два перекрёстных члена.",
"dp.step7": "Делим на −2. Слева сумма произведений соответствующих компонент. Справа длины, умноженные на косинус угла. Два вычисления, одно число: двигайте **a** или **b** и смотрите, как оба остаются равными.",
"dp.step8": "Дадим имя: **a**·**b**, скалярное произведение. Компоненты дают его без измерения угла; геометрия говорит, что оно значит: |**a**||**b**| cos θ. А урок 0.5 уже нарисовал его: |**a**|, умноженное на тень **b** на **a**, — это прямоугольник площадью **a**·**b**. Одно число, три лица; третье лицо освещает сферу в последней сцене.",
"dp.ch1": "Найдите **a** и **b**, для которых Σaᵢbᵢ = 0, но ни одна стрелка не нулевая.",
"dp.ch1Hint": "Поменяйте местами компоненты **a** и смените один знак: **b** = (−a₂, a₁).",
"dp.ch2": "Сделайте так, чтобы оба пути дали отрицательное число.",
"dp.ch2Success": "После 90° тень смотрит назад: прямоугольник заштрихован, его площадь считается отрицательной.",
"dp.ch3": "Сделайте **a**·**b** = |**a**|².",
"dp.ch3Success": "Подходит **b** = **a**, а также любое **b**, чья тень на **a** длиной ровно |**a**|; почему — покажет урок 1.5.",
"dp.ch4": "Сделайте **a**·**b** = 0, не обнуляя ни одной стрелки.",
"dp.ch4Hint": "Тяните **b** к пунктирной прямой.",
"dp.ch4Hint2": "Ответ в целых числах: **a** = (2, 1), **b** = (−1, 2).",
"dp.ch5": "Не трогая **a**, сделайте **a**·**b** как можно больше при |**b**| = 2.",
"dp.ch6": "Найдите **b** с |**b**| = 2 и **a**·**b** = −2|**a**| — самое отрицательное значение.",
"dp.ch7": "Добейтесь, чтобы лицо яркости показало 0.500: лампа под углом 60°.",
"dp.ch8": "Сделайте **a**·**b** = 0 в 3D, не обнуляя ни одной стрелки.",
"dp.ch9": "Поместите **b** по другую сторону диска (**a**·**b** < 0), сохранив b₃ > 0.",
"dp.ch10": "Поставьте P на терминатор.",
"dp.ch10Hint": "Пунктирная окружность — все точки с N·L = 0: перпендикулярная прямая из DP-2, изогнутая вокруг сферы близкой лампой.",
"dp.ch11": "Сделайте P как можно ярче, не двигая свет.",
"dp.ch12": "Включите сырое N·L и найдите самую тёмную точку.",
"dp.routes": "Σaᵢbᵢ = {dot}; |a||b| cos θ = {rhs}; прямоугольник |a| × тень = {rect}; θ = {th}. Одно число тремя путями.",
"dp.perpNote": " Обе стрелки ненулевые, а скалярное произведение равно 0: они перпендикулярны.",
"dp.negNote": " Число отрицательное: угол больше 90°, прямоугольник заштрихован.",
"dp.zeroBoth": "Обе стрелки нулевые: направления нет, значит нет ни угла, ни тени, ни прямоугольника. Σaᵢbᵢ по-прежнему считается: {dot}.",
"dp.zeroA": "У a = 0 нет направления: нет ни угла, ни оси, на которую падала бы тень, поэтому |a||b| cos θ и прямоугольник не определены. Σaᵢbᵢ по-прежнему считается: {dot}.",
"dp.zeroA2": "У a = 0 нет ни перпендикулярной прямой, ни тени: полуплоскости, угол и прямоугольник пропали. Σaᵢbᵢ по-прежнему считается: {dot}.",
"dp.zeroB": "b = 0: тень на a равна 0, площадь прямоугольника тоже. Но у b нет направления, поэтому угол, |a||b| cos θ и яркость не определены. Σaᵢbᵢ = {dot}.",
"dp.lampReadout": "В точке P: N·L = {ndotl}, θ = {th}, яркость max(0, N·L) = {bright}.",
"dp.lampLit": " P повёрнута к лампе.",
