"lc.tipRise": "AD: высота точки A над прямой стороны a.",
"lc.tipRest": "DB: часть стороны a за основанием D.",
"lc.tipRest2": "Квадрат на катете DB прямоугольного треугольника ADB.",
"lc.tipRise2": "Квадрат на катете AD прямоугольного треугольника ADB.",
"lc.tipD": "Расстояние от плеча до цели.",
"lc.tipCosRaw": "cos φ по теореме косинусов, ещё не зажатый; он может выйти за [−1, 1].",
"lc.tipCosC": "cos φ, зажатый в [−1, 1], чтобы arccos существовал.",
