"lc.solve": "РЕШЕНИЕ",
"lc.target": "Цель",
"lc.elbowDown": "Локоть вниз",
"lc.cosRaw": "cos φ сырой",
"lc.clamped": "Зажатый",
"lc.reach": "Досягаемость",
"lc.ikFormula": "Решение для двух костей",
"lc.triangleValues": "Значения треугольника",
"lc.derivation": "Вывод теоремы косинусов",
"lc.corrTip": "Две равные полосы со знаком",
"lc.pTip": "Тень b на a со знаком",
"lc.qTip": "Тень a на b со знаком",
"lc.cut0": "Три квадрата, по одному на каждой стороне. Пифагор обещает a² + b² = c², но только для прямого угла. Здесь a² + b² = {a2} + {b2} = {pyth}, а c² = {c2}. ",
"lc.cutZero": "Угол прямой, и числа сходятся: это теорема Пифагора, ничего не пропало.",
"lc.cutMissing": "Не хватает {missing} единиц площади. Куда они делись?",
"lc.cutExtra": "c² больше, чем a² + b², на {extra}. Откуда взялась лишняя площадь? (Угол тупой: полосы ниже будут считаться отрицательными.)",
"lc.cut1": "Посветим прямо сверху на сторону a. Сторона b отбрасывает на неё тень длины b cos θ (урок 0.4: косинус — это тень палочки длины 1).",
"lc.cut2": "Отрежем от квадрата на a полосу такой ширины. Её площадь a × (b cos θ).",
"lc.cut3": "Теперь посветим на сторону b: a отбрасывает на неё тень a cos θ. Отрежем полосу такой ширины от квадрата на b. Её площадь b × (a cos θ) — то же самое число. Два разных прямоугольника, одна площадь: a·b·cos θ.",
"lc.cut4": "Что осталось от двух квадратов: прямоугольник a × DB и прямоугольник b × EA.",
"lc.cut5": "Квадрат на c тоже можно разрезать: опустим высоту из C на c и продолжим её. Два прямоугольника, c × FB и c × AF.",
"lc.cut6": "Смотрите, как движется остаток от a. Сначала он наклоняется: верхняя сторона сдвигается вбок, а основание и высота остаются прежними, поэтому площадь не меняется.",
"lc.cut7": "Затем он поворачивается на четверть оборота вокруг B. Поворот ничего не меняет в площади.",
"lc.cut8": "Выпрямим его обратно: это в точности прямоугольник c × FB. Остаток от a стал первой частью c².",
"lc.cut9": "Остаток от b исполняет тот же танец вокруг A (наклон, четверть оборота против часовой стрелки, наклон) и ложится как c × AF. Вместе они заполняют квадрат на c: c² = a·DB + b·EA.",
"lc.cut10": "Теперь посчитаем площадь. Остатки — это квадраты минус полосы. Значит, c² = a² + b² − (полоса) − (полоса) = a² + b² − 2·a·b cos θ. Перетащите θ к 90°: тени сжимаются в точку, полосы исчезают, и это теорема Пифагора; более того, танец, который вы только что видели, и есть собственное доказательство Евклида. Перетащите θ за 90°: тени смотрят назад, полосы становятся заштрихованными (отрицательная площадь) и *прибавляются*.",
"lc.cut11": "Ещё раз взглянем на полосу: её площадь — длина стороны a, умноженная на тень стороны b на ней. В следующих уроках стороны станут стрелками, которые пишут жирным: **a**, **b**, с длинами |**a**|, |**b**|; полоса — это |**a**| (|**b**| cos θ). Урок 1.4 даст этому произведению имя — скалярное произведение **a**·**b**, новый смысл точки (не обычное умножение) — и покажет, что угол для него вовсе не нужен. Тогда теорема косинусов читается так: |**a** − **b**|² = |**a**|² + |**b**|² − 2 **a**·**b**: Пифагор с двумя вырезанными прямоугольниками.",
"lc.cut4Debt": " Здесь полоса шире своего квадрата: заштрихованный остаток — это долг, площадь со знаком минус.",
"lc.cutNoSquare": " c = 0: квадрата на c нет; переместите A, чтобы продолжить.",
"lc.proof0": "Снова ваш треугольник: стороны a и b сходятся в C под углом θ = {th}°; c — расстояние между их концами. ",
"lc.proofRight": "Угол прямой, так что теорема Пифагора уже работает; шаги ниже показывают, почему общая формула с ней согласна.",
"lc.proofNotRight": "Прямого угла нет, поэтому Пифагор пока не применим.",
"lc.proof1": "Опустим перпендикуляр из A на прямую стороны a. Его основание назовём D. Теперь прямые углы ЕСТЬ.",
"lc.proof2": "CD — тень b на a: CD = b cos θ. Высота AD = b sin θ.",
"lc.proof3": "Остаток стороны a — это DB = a − b cos θ. (Если θ > 90°, то b cos θ отрицательно и D лежит позади C: DB длиннее a. Формуле всё равно.)",
"lc.proof4": "Треугольник ADB прямоугольный, прямой угол при D. Пифагор: c² = DB² + AD².",
"lc.proof5": "Подставим два катета, которые мы назвали.",
"lc.proof6": "Раскроем квадрат: (a − b cos θ)² = a² − 2ab cos θ + b² cos² θ. Среднее слагаемое — та самая поправка: это две полосы первой сцены, записанные на языке алгебры.",
"lc.proof7": "b² cos² θ + b² sin² θ: два куска одного и того же квадрата.",
"lc.proof8": "cos² θ + sin² θ = 1 (точка единичной окружности на расстоянии 1). Два куска сливаются в b².",
"lc.proof9": "Готово: c² = a² + b² − 2ab cos θ. Перетащите θ к 90°: cos θ = 0, и это теорема Пифагора.",
"lc.proof2Zero": " Сейчас θ = 90°, поэтому тень нулевая и D совпадает с C.",
"lc.proof4Flat": " θ = 0° или 180° — сплющенный случай: AD = 0, и доказательство всё равно верно.",
"lc.cutTransport": "Движение внутри выбранного шага. Остановите его или двигайте ползунок, чтобы рассмотреть наклон и поворот; шаг объяснения при этом не меняется.",
"lc.fadeTransport": "Рассмотрите, как две плитки растворяются в квадрате на b. Ползунок меняет прозрачность, а не площадь и не шаг объяснения.",
"lc.pause": "Пауза",
