"va.read4": "r = s·a + t·b + u·c = {r}.",
"va.read4Plane": " При u = 0 r остаётся на плоскости a и b.",
"va.read5": "Уголок P' = {p} при w₁ = {w1} и w₂ = {w2}; каждая другая вершина сдвигается на свою w₁Δ₁ + w₂Δ₂.",
"va.ch1": "Сделайте **a + b = (0, 0)**, не обнуляя **a**.",
"va.ch1Success": "b = −a: путь по b отменяет путь по a.",
"va.ch2": "Сделайте |**a** + **b**| равным |**a**| + |**b**|, и чтобы ни одна стрелка не была нулевой.",
"va.ch2Hint": "Направьте a и b в одну сторону, например b = 2a.",
"va.ch2Success": "Длины складываются только у стрелок одного направления; любой угол между ними делает сумму короче.",
"va.ch3": "Разверните **a**, не меняя её длины.",
"va.ch4": "Сделайте **s·a** нулевым вектором.",
"va.ch4Success": "s = 0 даёт (0, 0) — единственный вектор без направления.",
"va.ch5": "Попадите в **r = (5, 3)**.",
"va.ch5Hint": "При a = (1, 2) и b = (3, −1): компоненты x дают s + 3t = 5, компоненты y — 2s − t = 3.",
"va.ch6": "Включите **Рисовать**, положите **a** и **b** на одну прямую и прокручивайте s и t. Что заполнят отметки?",
"va.ch6Hint": "Введите в панели b = 2a или b = −a.",
"va.ch6Success": "Прямую: две стрелки на одной прямой достают только до этой прямой, как ни прокручивай.",
"va.ch7": "Поднимите **r** строго вверх, в **(0, 3, 0)**.",
"va.ch7Hint": "Вверх смотрит только c: отключите a и b, поставив s = 0 и t = 0.",
"va.ch8": "Поставьте **u = 0** так, чтобы r не оказался в начале координат.",
"va.ch8Success": "Теперь r лежит на плоскости a и b: две стрелки дают плоскость, третья поднимает над ней.",
"va.ch9": "Улыбнитесь полностью (**w₁ = 1**) и откройте челюсть так, чтобы уголок вернулся на исходную высоту.",
"va.ch9Hint": "Улыбка поднимает уголок на 0.3, челюсть опускает его на 0.4·w₂.",
"va.ch10": "Заставьте лицо нахмуриться.",
"va.ch10Success": "Отрицательный вес прогоняет дельту в обратную сторону: веса могут быть любыми числами.",
