  "cp.ch1Hint": "Введите a = (1, 0, 0) и b = (0, 1, 0) в панели N (на телефоне — в полях под сценой).",
  "cp.ch1Success": "x × y = +z. Это сама формула, в любой системе координат; правило правой руки лишь описывает, как это выглядит в правой системе.",
  "cp.ch2": "Сделайте a × b нулевым вектором, не обнуляя ни a, ни b.",
  "cp.ch2Hint": "Направьте b вдоль той же прямой, что и a, например b = 2·a или b = −a.",
