  "cp.ch8Success": "Нормаль теперь смотрит от света, поэтому max(0, N·L) = 0. С включённым отсечением этот же треугольник просто исчезает.",
  "cp.ch9": "Оставьте порядок A → B → C и сдвиньте одну вершину так, чтобы грань стала чёрной.",
  "cp.ch9Hint": "Протащите C вниз через прямую AB, например C = (0, −2, 1): спереди обход A → B → C теперь идёт по часовой стрелке, и нормаль поворачивается к −z.",
  "cp.read1": "{name} = {c}. Его длина {len} равна площади параллелограмма, |a||b| sin θ = {area}. Он перпендикулярен обоим входам: ({name})·a = {ca}, ({name})·b = {cb}.",
  "cp.read1Swap": " Порядок b × a: та же прямая и та же длина, что у a × b, противоположное направление.",
  "cp.read1Par": "a и b лежат на одной прямой: параллелограмм сплющен, его площадь 0, и {name} = (0, 0, 0). Нулевой вектор — нормальный ответ; ошибку даёт только его нормализация.",
  "cp.read1Zero": "Одна стрелка нулевой длины: параллелограмма нет, {name} = (0, 0, 0), а угол θ не определён.",
  "cp.read2Ccw": "ax·by − ay·bx = {p} − {q} = {sa}: положительно, значит поворот от a к b идёт против часовой стрелки. Площадь параллелограмма {abs}.",
  "cp.read2Cw": "ax·by − ay·bx = {p} − {q} = {sa}: отрицательно, значит поворот от a к b идёт по часовой стрелке, и параллелограмм заштрихован. Площадь по-прежнему {abs}; знак — это только ориентация.",
  "cp.read2Line": "ax·by − ay·bx = {p} − {q} = {sa}: a и b лежат на одной прямой, параллелограмм сплющен.",
  "cp.read3": "Порядок {order}: e₁ = {e1}, e₂ = {e2}, e₁ × e₂ = {n}, значит N = {N}. N·L = {ndotl}, яркость max(0, N·L) = {bright}.",
  "cp.read3Lit": " Лицевая сторона грани повёрнута к свету.",
  "cp.read3Dark": " Нормаль смотрит от света: где бы грань ни рисовалась, она чёрная.",
  "cp.read3Cull": " Отсечение задних граней включено: грань рисуется, только пока её вершины идут на экране против часовой стрелки, то есть пока N смотрит на камеру. Обойдите её сзади, и она исчезнет.",
