  "pt.hintXd": "d² = {d2} · d = {d}",
  "pt.idle5Mouse": "Тяните X · меняйте r в панели [N]",
  "pt.idle5Touch": "Тяните X · меняйте r в полях под сценой",
  "pt.formula1": "Расстояние между P и Q",
  "pt.formula2": "Площади в разрезании",
  "pt.formula3": "Расстояние в 3D, два шага",
  "pt.formula4": "Расстояние в n измерениях",
  "pt.formula5": "Квадрат расстояния против квадрата радиуса",
  "pt.dis0": "Четыре копии треугольника лежат в квадрате со стороной **a + b**, по прямому углу в каждом углу. Их длинные стороны огораживают наклонный квадрат со стороной c: незакрытая площадь равна **c²**.",
  "pt.dis1": "Посчитаем большой квадрат двумя способами. Целиком: (a + b)² = {big}. По кусочкам: четыре треугольника занимают 4 · ½ab = {tris}, значит наклонный квадрат c² = {c2}.",
  "pt.dis2": "Сдвинем правый верхний треугольник вниз и влево. Он не поворачивается и не меняет формы: вместе с левой нижней копией он замыкает прямоугольник a на b.",
  "pt.dis3": "Сдвинем два других, один вверх, другой вправо. Они замыкают прямоугольник b на a в противоположном углу.",
  "pt.dis4": "Тот же большой квадрат, те же четыре треугольника, значит незакрытая площадь по-прежнему {c2}. Но теперь это два квадрата: a² + b² = {a2} + {b2}. Значит, **a² + b² = c²**.",
  "pt.room0": "Сначала пройдём по полу: катеты dx и dz, между ними прямой угол. Пифагор на полу: f² = dx² + dz² = {f2}.",
  "pt.room1": "Теперь поднимемся на dy. Диагональ пола f и вертикальный катет встречаются под прямым углом: новый треугольник, стоящий вертикально. Снова Пифагор: d² = f² + dy² = {s2}.",
  "pt.room2": "Оба шага вместе: d² = dx² + dy² + dz², d = {s}. Поверните вид: прямые углы остаются прямыми с любой стороны.",
  "pt.read1": "P = ({P}), Q = ({Q}): катеты dx = {dx} и dy = {dy}; квадраты {dx2} + {dy2} = {d2}; по прямой d = {d}, по сетке {walk}.",
  "pt.read1Line": " Один катет равен нулю: прямая идёт вдоль сетки, поэтому она ровно такой же длины, как путь по сетке.",
  "pt.read1Negative": " Катет отрицателен, потому что Q левее или ниже P; его квадрат всё равно положителен, так что расстоянию это безразлично.",
  "pt.read1Zero": "P и Q совпадают: оба катета равны 0, и расстояние равно 0.",
  "pt.read2": "a = {a}, b = {b}: большой квадрат (a + b)² = {big}; четыре треугольника {tris}; незакрыто c² = {c2}, c = {c}; и a² + b² = {a2} + {b2} = {c2}.",
  "pt.read3": "Пол: f² = dx² + dz² = {dx2} + {dz2} = {f2}. Вверх: d² = f² + dy² = {f2} + {dy2} = {s2}, значит d = {s}.",
  "pt.read3Zero": "P и Q совпадают: все катеты равны 0, и расстояние равно 0.",
  "pt.read5": "X = ({x}, {y}): d² = {d2} и r² = {r2}. С корнями: d = {d} и r = {r}.",
  "pt.read5In": " d² < r², значит X внутри, и d < r говорит то же самое.",
  "pt.read5On": " d² = r², значит X ровно на окружности.",
  "pt.read5Out": " d² > r², значит X снаружи, и d > r говорит то же самое.",
  "pt.readN": "n = {n}: разности {legs}; квадраты {squares}; сумма {d2}; расстояние d = {d}.",
  "pt.ndDims": "измерений n",
