  "pt.ndCaption": "Разности и их квадраты, по строке на измерение",
  "pt.ch1": "Сделайте расстояние ровно 5 с другими точками, не (1, 2) и (4, 6).",
  "pt.ch1Hint": "Катеты 3 и 4 работают в любом месте сетки. Катеты 5 и 0 тоже.",
  "pt.ch2": "Сделайте прямую ровно такой же длины, как путь по сетке.",
  "pt.ch2Hint": "Когда перелёт такой же длины, как поездка? Когда ехать можно только по одной улице.",
  "pt.ch2Success": "Один катет равен нулю, поэтому d = √(dx²) = |dx|: треугольник сплющился в отрезок.",
  "pt.ch3": "Доведите сдвиг до конца и сравните, что осталось незакрытым.",
  "pt.ch4": "Найдите другие катеты a и b, при которых длинная сторона c — целое число.",
  "pt.ch4Hint": "Масштабируйте треугольник 3-4-5: умножьте 3, 4 и 5 на одно и то же число, например на 0.6.",
