"bas.read4Oblique": "Эти линейки не ортонормированы: показания ({r1}, {r2}, {r3}) больше не координаты ({c1}, {c2}, {c3}), и сборка по показаниям промахивается мимо v на {gap}. Настоящие координаты получаются решением небольшой системы (урок 2.9).",
"bas.read4Flat": "Три линейки лежат в одной плоскости: большинство векторов из них вообще не собрать, поэтому координат нет.",
"bas.ch1": "Перетащите u₂ так, чтобы решётка схлопнулась в одну прямую (обе линейки ненулевые).",
"bas.ch1Hint": "Положите u₂ на прямую u₁, например u₁ = (1, 2) и u₂ = (2, 4).",
"bas.ch2": "Оставьте v = (3, 4) и выберите линейки, в которых v читается как (2, 1).",
"bas.ch2Hint": "Нужно 2·u₁ + u₂ = (3, 4). Возьмите u₁ = (1, 1) и найдите u₂.",
"bas.ch3": "Вытащите c из стены, чтобы три стрелки порождали всё пространство.",
"bas.ch3Hint": "Сфокусируйте конец c (Tab) и нажмите PageUp: он сдвинется по z, из плоскости z = 0.",
"bas.ch4": "Снова сделайте оболочкой плоскость, но не стену z = 0.",
"bas.ch4Hint": "Сначала наклоните a или b из стены, потом подтащите c к плоскости a и b: она прилипнет к ней.",
"bas.ch5": "Поверните оси так, чтобы P лежала на первой новой оси: c₂ = 0.",
"bas.ch5Hint": "P = (3, 1) смотрит примерно на 18° вверх от оси x.",
"bas.ch6": "Поверните оси так, чтобы P = (3, 1) читалась как (1, 3).",
"bas.ch6Success": "При θ = 90° линейки — это (0, 1) и (1, 0): та же стрелка, числа в другом порядке.",
"bas.ch7": "Выключите **ортонормированность** и согните линейку так, чтобы призрак промахнулся мимо v больше чем на 1.",
"bas.ch7Hint": "Флажок в панели N (на телефоне — в чипах под сценой). Потом тяните конец u₂ к u₁.",
"bas.ch8": "Снова включите **ортонормированность** после того, как согнули линейки.",
"bas.ch8Success": "Грам — Шмидт снова выровнял линейки: показания стали координатами, и призрак сел на v.",
